const severityClass = (value: string | undefined) => (value || 'SAFE').toLowerCase()
const riskLabel = (score: number): Severity => score >= 71 ? 'CRITICAL' : score >= 51 ? 'WARNING' : score >= 31 ? 'CAUTION' : 'SAFE'
const timeLabel = (value?: string | null) => {
  if (!value) return '—'
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return value
  return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
}
const formatNumber = (value: number) => new Intl.NumberFormat('en-IN').format(Math.round(value))
const formatPercent = (value: number) => `${Number(value).toFixed(value % 1 === 0 ? 0 : 1)}%`

function StatusChip({ value, dot = true }: { value: string; dot?: boolean }) {
  return <span className={`status-chip ${severityClass(value)}`}>{dot && <span className="status-dot" />}{value}</span>
}

function ModePill({ mode = 'SIMULATION MODE', compact = false }: { mode?: string; compact?: boolean }) {
  return <span className={`mode-pill ${compact ? 'compact' : ''}`}><span className="mode-live-dot" />{mode}</span>
}

function MetricCard({ label, value, sub, icon, tone = 'blue', trend, onClick }: { label: string; value: string | number; sub?: string; icon: ReactNode; tone?: string; trend?: 'up' | 'down' | 'flat'; onClick?: () => void }) {
  return (
    <div className={`metric-card tone-${tone} ${onClick ? 'is-clickable' : ''}`} onClick={onClick}>
      <div className="metric-top"><span className="metric-label">{label}</span><span className="metric-icon">{icon}</span></div>
      <div className="metric-value">{value}</div>
      {sub && <div className="metric-sub">{trend === 'up' && <TrendingUp size={13} />}{trend === 'down' && <TrendingDown size={13} />}{sub}</div>}
    </div>
  )
}

function ProgressBar({ value, tone = 'blue', height = 7 }: { value: number; tone?: string; height?: number }) {
  return <div className="progress-track" style={{ height }}><div className={`progress-fill ${tone}`} style={{ width: `${Math.min(100, Math.max(0, value))}%` }} /></div>
}

function SectionHeading({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) {
  return <div className="section-heading"><div><div className="eyebrow">{eyebrow}</div><h2>{title}</h2>{description && <p>{description}</p>}</div>{action}</div>
}

function MiniChart({ data, dataKey = 'value', color = '#4b9bff', height = 84, gradient = true }: { data: Array<Record<string, number | string>>; dataKey?: string; color?: string; height?: number; gradient?: boolean }) {
  return <ResponsiveContainer width="100%" height={height}>
    <AreaChart data={data} margin={{ top: 4, right: 0, left: 0, bottom: 0 }}>
      <defs><linearGradient id={`g-${color.replace('#', '')}`} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={color} stopOpacity={gradient ? 0.3 : 0} /><stop offset="100%" stopColor={color} stopOpacity={0} /></linearGradient></defs>
      <Area type="monotone" dataKey={dataKey} stroke={color} strokeWidth={2.3} fill={gradient ? `url(#g-${color.replace('#', '')})` : 'none'} dot={false} />
    </AreaChart>
  </ResponsiveContainer>
}

function QrVisual({ value }: { value: string }) {
  const size = 21
  const hash = Array.from(value).reduce((acc, char, index) => (acc + char.charCodeAt(0) * (index + 11)) % 997, 17)
  const isFinder = (x: number, y: number, ox: number, oy: number) => x >= ox && x < ox + 7 && y >= oy && y < oy + 7 && (x === ox || x === ox + 6 || y === oy || y === oy + 6 || (x >= ox + 2 && x <= ox + 4 && y >= oy + 2 && y <= oy + 4))
  const cells: Array<{ x: number; y: number }> = []
  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      const finder = isFinder(x, y, 0, 0) || isFinder(x, y, 14, 0) || isFinder(x, y, 0, 14)
      const reserved = (x < 9 && y < 9) || (x > 11 && y < 9) || (x < 9 && y > 11)
      const filled = finder || (!reserved && ((x * 13 + y * 7 + hash + x * y) % 5 === 0 || (x + y + hash) % 11 === 0))
      if (filled) cells.push({ x, y })
    }
  }
  return <svg className="qr-svg" viewBox="0 0 21 21" role="img" aria-label={`QR code for ${value}`}>
    <rect width="21" height="21" fill="#fff" />
    {cells.map((cell) => <rect key={`${cell.x}-${cell.y}`} x={cell.x} y={cell.y} width="1" height="1" fill="#07111f" />)}
  </svg>
}

